/* ------------------------------------------------------------------ utils */

/** "$3.00" | "3.00" | "free" | "" | "?" -> number ($ per 1M tokens) or null */
function parseRate(text) {
  if (text == null) return null
  const s = String(text).trim()
  if (!s || s === '?') return null
  if (s.toLowerCase() === 'free') return 0
  const n = Number.parseFloat(s.replace(/[$,\s]/g, ''))
  return Number.isFinite(n) && n >= 0 ? n : null
}

function fmtTokens(n) {
  const v = Number(n) || 0
  if (v >= 1_000_000) return `${(v / 1_000_000).toFixed(2)}M`
  if (v >= 1_000) return `${(v / 1_000).toFixed(1)}k`
  return String(v)
}

function fmtUsd(v) {
  if (v == null || !Number.isFinite(v)) return 'â€”'
  if (v === 0) return '$0.00'
  if (v < 0) return `âˆ’${fmtUsd(-v)}`
  if (v < 0.01) return `$${v.toFixed(4)}`
  if (v < 1) return `$${v.toFixed(3)}`
  return `$${v.toFixed(2)}`
}

/** Per-MTok catalogue rates: 4dp grid, float-artefact-proof, never rounded away. */
function fmtRate(v) {
  if (v == null || !Number.isFinite(v)) return 'â€”'
  const rounded = Math.round(v * 1e4) / 1e4
  // A positive rate must never render as free: below the 4dp grid, fall
  // back to 3 significant digits instead of showing $0.
  if (rounded === 0 && v > 0) return `$${String(Number(v.toPrecision(3)))}`
  return `$${String(rounded)}`
}

/** Local calendar day, not UTC â€” "today" must mean the user's today. */
function dayKey(ts) {
  const d = ts != null ? new Date(ts) : new Date()
  const p = n => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`
}

/** The local day `n` calendar days before `now` (DST-safe: no 86.4M ms math). */
function daysAgoKey(n, now) {
  const d = now != null ? new Date(now) : new Date()
  d.setDate(d.getDate() - n)
  return dayKey(d.getTime())
}

function num(v) {
  const n = Number(v)
  return Number.isFinite(n) && n > 0 ? n : 0
}

function tokensOf(b) {
  return num(b.input) + num(b.output) + num(b.cacheRead) + num(b.cacheWrite)
}

function validRates(r) {
  return !!r && ['input', 'output', 'cache'].every(k => typeof r[k] === 'number' && Number.isFinite(r[k]) && r[k] >= 0)
}

